import { useEffect } from "react";
import { tracker } from "travel-platform";

// Registers for long-task and event-timing entries; their delivery happens
// outside the measured steps.
export function useLongTaskObserver() {
    useEffect(() => {
        if (typeof PerformanceObserver === "undefined")
            return undefined;
        const supported = PerformanceObserver.supportedEntryTypes ?? [];
        const types = ["longtask", "event"].filter((type) => supported.includes(type));
        if (!types.length)
            return undefined;
        const observer = new PerformanceObserver((list) => {
            const entries = list.getEntries().slice(0, 10).map((entry) => ({ type: entry.entryType, name: entry.name, duration: Math.round(entry.duration) }));
            tracker.push("sink", "perf.entries", { entries });
        });
        for (const type of types)
            observer.observe({ type, buffered: false });
        return () => observer.disconnect();
    }, []);
}
