// The page's first-party trackers: the page view, consent state, render
// timings ("squeak") after each results commit, and an error reporter. They
// render nothing.
import { useEffect, useRef } from "react";
import { exportSpans, tracker, usePage, useSearchState, useUser } from "travel-platform";
import { useLongTaskObserver } from "./useLongTaskObserver.js";
import { ConsentState } from "./ConsentState.jsx";

function usePageView(page, user) {
    useEffect(() => {
        tracker.setPageContext({ pageName: page.pageName, loggedIn: user.loggedIn, layout: "desktop" });
        tracker.track("page.view", { pageName: page.pageName, referrer: "", entry: "hydrate" });
    }, [page, user]);
}

function useRenderTimings(searchState) {
    const commits = useRef(0);
    useEffect(() => {
        if (searchState.isPending)
            return;
        commits.current++;
        tracker.push("squeak", "render", { commit: commits.current, filters: searchState.state.filters.length, sort: searchState.state.sort, page: searchState.state.page });
        exportSpans();
    }, [searchState.state, searchState.isPending]);
}

function useErrorReporter() {
    useEffect(() => {
        const onError = (event) => tracker.push("sink", "window.error", { message: String(event.message) });
        window.addEventListener("error", onError);
        return () => window.removeEventListener("error", onError);
    }, []);
}

export default function PageTrackers() {
    const page = usePage();
    const user = useUser();
    const searchState = useSearchState();
    usePageView(page, user);
    useRenderTimings(searchState);
    useErrorReporter();
    useLongTaskObserver();
    return <ConsentState />;
}
